using Contoso.Services;

namespace Contoso.Services.Tests;

[TestClass]
public sealed class ServiceRegistryTests
{
    private readonly ServiceRegistry _registry;

    public ServiceRegistryTests()
    {
        _registry = new ServiceRegistry();
    }

    [TestMethod]
    public void Register_And_Resolve_ReturnsRegisteredInstance()
    {
        var service = new FakeLogger();

        _registry.Register<ILogger>(service);

        var resolved = _registry.Resolve<ILogger>();
        Assert.AreSame(service, resolved);
    }

    [TestMethod]
    public void Resolve_Unregistered_ReturnsNull()
    {
        var result = _registry.Resolve<ILogger>();

        Assert.IsNull(result);
    }

    [TestMethod]
    public void Resolve_ReturnsSameInstance_OnMultipleCalls()
    {
        var service = new FakeLogger();
        _registry.Register<ILogger>(service);

        var first = _registry.Resolve<ILogger>();
        var second = _registry.Resolve<ILogger>();

        Assert.AreSame(first, second);
    }

    [TestMethod]
    public void Clear_RemovesAllServices()
    {
        _registry.Register<ILogger>(new FakeLogger());
        _registry.Register<INotifier>(new FakeNotifier());

        _registry.Clear();

        Assert.IsNull(_registry.Resolve<ILogger>());
        Assert.IsNull(_registry.Resolve<INotifier>());
        Assert.IsEmpty(_registry.GetAll());
    }

    [TestMethod]
    public void Remove_RemovesSpecificService()
    {
        _registry.Register<ILogger>(new FakeLogger());
        _registry.Register<INotifier>(new FakeNotifier());

        _registry.Remove<ILogger>();

        Assert.IsNull(_registry.Resolve<ILogger>());
        Assert.IsNotNull(_registry.Resolve<INotifier>());
    }

    // Test doubles
    private interface ILogger;
    private interface INotifier;
    private sealed class FakeLogger : ILogger;
    private sealed class FakeNotifier : INotifier;
}

